// Des: Tests for config loading and checks
// Flo: parse JSON samples > check defaults, overrides, bad values, path expansion, shipped file
// I/O: sample JSON text (in code) > pass or fail
// Run: cd E:\zz-base-home\as-apps\in-inte\or-orac-webs && zig build test -Dfile=cf-conf-load-test.zig
// ===================================================================
const std = @import("std"); const cfgz = @import("cf-conf-load.zig");
fn arenNew() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.testing.allocator); }
test "empty object gives safe defaults" { var aren = arenNew(); defer aren.deinit(); const conf = try cfgz.confParse(aren.allocator(), "{}"); try std.testing.expectEqual(@as(u32, 10), conf.capz_acct_dayz); try std.testing.expectEqual(@as(u32, 5), conf.capz_mone_dayz); try std.testing.expectEqualStrings("https://cloud.oracle.com", conf.base_appz_main); }
test "keys override and unknown keys are ignored" { var aren = arenNew(); defer aren.deinit(); const conf = try cfgz.confParse(aren.allocator(), "{\"capz_acct_dayz\":1,\"zzzz\":5,\"type_dely_msec\":[10,20]}"); try std.testing.expectEqual(@as(u32, 1), conf.capz_acct_dayz); try std.testing.expectEqual(@as(u32, 20), conf.type_dely_msec[1]); }
test "bad values are rejected" { var aren = arenNew(); defer aren.deinit(); const bads = [_][]const u8{ "{\"type_dely_msec\":[300,100]}", "{\"quie_hour_rang\":[25,1]}", "{\"retr_coun_maxz\":0}", "{\"base_urlz_main\":\"ftp://x\"}", "{\"base_appz_main\":\"x\"}", "{\"lang_main_code\":\"vi\"}", "{\"noti_chai_orde\":[\"fax\"]}", "not json" }; for (bads) |txt| try std.testing.expectError(error.BadConfig, cfgz.confParse(aren.allocator(), txt)); }
test "tilde expands with home, empty home refused" { const allo = std.testing.allocator; const out = try cfgz.pathExpa(allo, "/home/u", "~/.or-prof"); defer allo.free(out); try std.testing.expectEqualStrings("/home/u/.or-prof", out); try std.testing.expectError(error.BadConfig, cfgz.pathExpa(allo, "", "~/x")); const abs = try cfgz.pathExpa(allo, "", "/abs/p"); defer allo.free(abs); try std.testing.expectEqualStrings("/abs/p", abs); }
test "data and secret folders mirror the app path, per OS" { const allo = std.testing.allocator; const conf: cfgz.Conf = .{}; try std.testing.expectEqualStrings("E:\\.zz-base-home-tena\\as-apps\\in-inte\\or-orac-webs", conf.data_loca_wind); try std.testing.expectEqualStrings("~/.zz-base-home-tena/as-apps/in-inte/or-orac-webs", conf.data_loca_unix); const dir = try cfgz.dataDir(allo, "/home/u", conf); defer allo.free(dir); try std.testing.expect(std.mem.find(u8, dir, "in-inte") != null); const sec = try cfgz.secrDir(allo, "/home/u", conf); defer allo.free(sec); try std.testing.expectEqualStrings("/home/u/.zz-base-home-secr/as-apps/in-inte/or-orac-webs", sec); const sub = try cfgz.subDir(allo, "/home/u", conf, "stat"); defer allo.free(sub); try std.testing.expect(std.mem.endsWith(u8, sub, "stat")); }
test "missing config file returns defaults" { var aren = arenNew(); defer aren.deinit(); const conf = try cfgz.confLoad(aren.allocator(), std.testing.io, "no-such-file-zz.json"); try std.testing.expectEqual(@as(u32, 30), conf.capz_acce_dayz); }
test "label and path overrides parse" { var aren = arenNew(); defer aren.deinit(); const conf = try cfgz.confParse(aren.allocator(), "{\"labl_over\":{\"logi_subm\":[\"Go\"]},\"path_over\":{\"p_keys\":\"/keys\"}}"); try std.testing.expectEqualStrings("Go", conf.labl_over.map.get("logi_subm").?[0]); try std.testing.expectEqualStrings("/keys", conf.path_over.map.get("p_keys").?); }
test "the shipped aa-conf-main.json parses and agrees with the code defaults" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const conf = try cfgz.confLoad(aren.allocator(), std.testing.io, "aa-conf-main.json"); const dflt: cfgz.Conf = .{}; try std.testing.expectEqual(dflt.capz_acct_dayz, conf.capz_acct_dayz); try std.testing.expectEqual(dflt.capz_prod_dayz, conf.capz_prod_dayz); try std.testing.expectEqual(dflt.capz_data_dayz, conf.capz_data_dayz); try std.testing.expectEqual(dflt.capz_mone_dayz, conf.capz_mone_dayz); try std.testing.expectEqual(dflt.capz_acce_dayz, conf.capz_acce_dayz); try std.testing.expectEqual(dflt.capz_sett_dayz, conf.capz_sett_dayz); try std.testing.expectEqual(dflt.capz_help_dayz, conf.capz_help_dayz); try std.testing.expectEqual(dflt.wait_maxx_minu, conf.wait_maxx_minu); try std.testing.expectEqual(dflt.cool_perc_caps, conf.cool_perc_caps); try std.testing.expectEqual(dflt.acti_dely_secs[1], conf.acti_dely_secs[1]); try std.testing.expectEqualStrings(dflt.base_urlz_main, conf.base_urlz_main); try std.testing.expectEqualStrings(dflt.base_appz_main, conf.base_appz_main); try std.testing.expectEqualStrings(dflt.base_docz_main, conf.base_docz_main); try std.testing.expectEqualStrings(dflt.data_loca_wind, conf.data_loca_wind); try std.testing.expectEqualStrings(dflt.data_loca_unix, conf.data_loca_unix); try std.testing.expectEqualStrings(dflt.secr_loca_main, conf.secr_loca_main); try std.testing.expectEqual(@as(usize, 2), conf.flow_list.len); try std.testing.expectEqualStrings("daily-check", conf.flow_list[0].name); }
test "account limits: defaults (3) and bounds" { const dflt: cfgz.Conf = .{}; try std.testing.expectEqual(@as(u32, 3), dflt.acct_maxx_coun); try std.testing.expectEqual(@as(u32, 300), dflt.acct_gap_secs[0]); var aren = arenNew(); defer aren.deinit(); const bads = [_][]const u8{ "{\"acct_maxx_coun\":0}", "{\"acct_maxx_coun\":21}", "{\"acct_gap_secs\":[900,100]}" }; for (bads) |txt| try std.testing.expectError(error.BadConfig, cfgz.confParse(aren.allocator(), txt)); const okay = try cfgz.confParse(aren.allocator(), "{\"acct_maxx_coun\":10,\"acct_gap_secs\":[60,120]}"); try std.testing.expectEqual(@as(u32, 10), okay.acct_maxx_coun); }
